package com.medtrack.inventory.entity;
import static org.junit.jupiter.api.Assertions.*; import com.medtrack.batch.entity.*; import com.medtrack.medicine.entity.Medicine; import com.medtrack.supplier.entity.Supplier; import com.medtrack.warehouse.entity.*; import java.time.LocalDate; import java.util.*; import java.util.concurrent.*; import org.junit.jupiter.api.Test;
class InventoryBalanceConcurrencyTest { @Test void ac03_neverAllowsNegativeAvailableQuantityUnderConcurrentReservations() throws Exception {Warehouse w=new Warehouse("CW","Central",WarehouseType.CENTRAL_WAREHOUSE,"Address",null,null,null,WarehouseStatus.ACTIVE);Medicine m=new Medicine("MED-ANT-00042","Drug",null,null,"TABLET","500mg","BOX",null,0,90,null);Batch b=new Batch("B-1",m,new Supplier("Supplier","SUP",null,null,null),LocalDate.now().minusDays(1),LocalDate.now().plusDays(365),10,BatchStatus.ACTIVE);InventoryBalance balance=new InventoryBalance(w,b,new StorageLocation(w,"A","1","1","A-1-1"));balance.receive(10);ExecutorService pool=Executors.newFixedThreadPool(10);List<Future<Boolean>> results=new ArrayList<>();for(int i=0;i<50;i++)results.add(pool.submit(()->{try{balance.reserve(1);return true;}catch(IllegalArgumentException e){return false;}}));int successes=0;for(Future<Boolean> result:results)if(result.get())successes++;pool.shutdown();assertEquals(10,successes);assertEquals(0,balance.getAvailableQuantity());assertEquals(10,balance.getReservedQuantity());assertEquals(10,balance.getPhysicalQuantity());}}
